-- GENERATED by `wfj generate` from data/gossip/gossip-55.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["5504eb420309ca58"] = { "Un po' di tortura rituale fa miracoli.", "." },
  ["550ab79ca6ee69fd"] = { "Chi lo sa? Comunque, è l'ultima volta che l'ho vista. Forse Frankal può darti informazioni migliori.\n\nNon voglio cambiare discorso, perché di certo il lavoro che fai per il comandante è importante, ma qui siamo su qualcosa di enorme. ENORME! Finora le nostre richieste di un esercito a ⟦Ironforge=Forgiardente⟧ sono cadute nel vuoto. A quanto pare siamo troppo impegnati a proteggere il regno, o qualche sciocchezza del genere. Quando avrai portato il tuo rapporto al comandante, torna quaggiù con qualche amico. Ci serve il tuo aiuto!", "." },
  ["550c26eefbf634ad"] = { "Chi riceve un ⟦Horde Commendation Signet=Anello d'Encomio dell'Orda⟧ è <un/una> <eroe/eroina> che va ben oltre il proprio dovere verso l'⟦Horde=Orda⟧. In tutte le capitali si trovano vari ufficiali dell'encomio per le fazioni dell'⟦Horde=Orda⟧: parla con quello della fazione con cui vuoi aumentare la reputazione, e dagli il numero di anelli che ti chiede!\n\nA proposito, durante lo sforzo bellico qui, se per i tuoi anelli preferisci una ricompensa materiale invece della reputazione, cerca il signore della guerra Gorchuk.", "." },
  ["55133b87269f9e0c"] = { "Un minatore? Non devi chiedere se, <ragazzo/ragazza>, solo dove! Quello che cerchi è Yarr, e credo che lo troverai nascosto allo ⟦Steelgrill's Depot=Scalo di Grigliafredda⟧.", "." },
  ["552aa8673321ac58"] = { "Vorrei inserire il codice segreto per ricevere il mio murloc da compagnia.", "." },
  ["553a49013b35439c"] = { "Ben fatto, soldato. Ancora qualcuno e le nostre stalle traboccheranno di cavalcature che la cavalleria porterà in battaglia!", "." },
  ["553fc8849097a676"] = { "Hai imparato molto, più di quanto io possa insegnarti. Va' da James Van Brunt: ti insegnerà ciò che io non posso.", "." },
  ["5545c28a8f3fd120"] = { "Miao!", "." },
  ["55463d22b5917413"] = { "E... pensi di sconfiggere gli Dei Primordiali?", "." },
  ["5561061882d6bcd3"] = { "Impara la ricetta.", "." },
  ["556298a83a615972"] = { "Hai sfacciatamente ignorato poteri che vanno oltre la tua comprensione.", "." },
  ["556783bdb7311055"] = { "Fermi! È l'ora di Omosh!", "." },
  ["556d34580e88f9fb"] = { "Che le benedizioni di Cenarius siano con te, {class}. La nostra guida, l'arcidruido Staghelm, conduce noi e tutta Teldrassil verso una vita nuova!", "." },
  ["557079561c1dd1ae"] = { "Credo che fossero gli ultimi. Meno male che hai fatto in tempo... Non sapevo per quanto ancora avrei potuto restare al riparo.", "." },
  ["5570a122bdade392"] = { "Muori, {name}. Elune non ti permetterà più di fare del male alle sue creature!", "." },
  ["557bd217d384c448"] = { "Non vengono molti scuoiatori qui a cercare addestramento, ma immagino di poterti insegnare qualcosa se sei <pronto/pronta>.", "." },
  ["5580345ef7f55bd9"] = { "Annalise? Sei tu?", "." },
  ["558474b67fc38e55"] = { "Avanti... MARSC!", "." },
  ["5587c85b9f6ff97f"] = { "Tu capo adesso, sì? Lunga vita a nuovo re!\n\nKreeg ti fa guardare liquore Gordok. Liquore di ogre migliore di tutti liquori, e liquore Gordok migliore di tutti liquori di ogre! Forse tu compra un po' da me, sì capo?!", "." },
  ["558cdfc772f1b895"] = { "Avete riconquistato qualche misero territorio. Patetico. In breve tempo torneranno a essere nostri!", "." },
  ["558f449a26ee1585"] = { "È meraviglioso, Rimblat! Persino questa terra immonda e spaccata può ancora guarire.", "." },
  ["5596b5611514f7cb"] = { "Allora, {name}, eccomi qui: ti racconto cos'è successo nella ⟦Swamp of Sorrows=Palude del Dolore⟧. Hic!", "." },
  ["55a41b2750f7d066"] = { "Questa guerra ha prosciugato il nostro popolo e le nostre risorse. Nemmeno qui su Teldrassil possiamo sfuggire alle sue ripercussioni. Perdonami se te lo chiedo, ma faresti una commissione per me?", "." },
  ["55b27e71fc9183b5"] = { "Vengo per te, patetica ⟦Alliance=Alleanza⟧!", "." },
  ["55b59eed0506d3b0"] = { "Torna qui!", "." },
  ["55c6356f338b54d6"] = { "%s comincia a eseguire il rituale del risveglio su Naralex.", "." },
  ["55cdb46f1b816b0a"] = { "Aiuto! Ci attaccano! I Ferroscuro!", "." },
  ["55d62041953d5d38"] = { "Be', salve. Hai l'aria di chi non disdegnerebbe guadagnare qualche moneta, eh? Lo leggo nei tuoi occhi. Sono il magnate Kebok, sovrintendente delle operazioni su Azeroth, e se cerchi ricchezze, forse posso organizzare qualcosa.", "." },
  ["55d7f2aa5901700c"] = { "Come va quel talismano, mon? Sembra proprio ora di mettere un altro po' di magia e di mojo nelle sue foglie. Gli serve un po' di fiore nel suo appassire. Dammelo qua e Maywiki lo sistema per bene.", "." },
  ["55d9160c543e62b9"] = { "La Torre di Brinarossa è stata presa dall'⟦Horde=Orda⟧!", "." },
  ["55dcea8a67db5aed"] = { "Timer di inizio partita disattivato.", "." },
  ["55e4741fb343991e"] = { "Questa volta abbiamo perso, ma non lasciarti abbattere. Concentrati sui tuoi attacchi speciali. Tieni lo scudo alto e vicino. Fallo, e la prossima volta la vittoria sarà nostra!", "." },
  ["55e712b5fcab7fb0"] = { "La modernizzazione è la chiave. Con una manovella e una leva puoi far fuoco con questo gioiellino con la forza di un ogre che tende un arco normale.", "." },
  ["55e914b1c6153078"] = { "Ascolta bene ciò che ti viene detto e non affrettarti a fidarti, né a diffidare. Perché anche gli amici perseguono i propri fini, {class}.\n\nIl nostro grande Capoguerra lo sa e, per dimostrare che nell'⟦Horde=Orda⟧ ci sono stregoni che non vogliono distruggerla dall'interno né prenderne il controllo, ho dato la mia disponibilità ad aiutare il nostro giovane capo in ogni modo possibile.", "." },
  ["55ea28f0f9aacc0c"] = { "Il grande santuario fu costruito molti anni fa dagli elfi della notte che un tempo abitavano questa terra.\n\nQuali segreti potrebbe custodire?", "." },
  ["55ed6c60bfbb2cb9"] = { "Per la gloria di ⟦Ironforge=Forgiardente⟧!", "." },
  ["55ed73f18a164d72"] = { "Mograine è caduto? Pagherai per questo tradimento!", "." },
  ["55f39ff085d7fcfe"] = { "Inseguimi, se hai coraggio! Io corro e non mi scoraggio!", "." },
  ["55f3baf50e6f2d82"] = { "Cosa?! Come hai fatto a sgattaiolare oltre il mio carceriere... ehm, servitore là fuori? Be', immagino sia meglio così. Le vendite sono un po' fiacche ultimamente.\n\nCome posso soddisfare i tuoi bisogni infernali, {class}?", "." },
  ["55f51f35d58c9d09"] = { "La mia risposta è Kel'Thuzad.", "." },
  ["55f75b0cf5065eab"] = { "Gli impiccioni pagheranno per la loro interferenza. Ritiriamoci nelle ombre!", "." },
  ["55fcbafc7e7cedab"] = { "Mi aspetto di sentir parlare del tuo successo, {name}. Ma se dovessi fallire, deludere le mie aspettative sarà l'ultima delle tue preoccupazioni.", "." },
})
